// themes/default/public/js/lib/utils.js
var addToast = (message, type) => {
  const notification = document.querySelector("template#notification").content.cloneNode(true).children[0];
  notification.classList.add(`is-${type}`);
  notification.querySelector(".message").innerText = message;
  document.getElementById("notifications-container").append(notification);
  setTimeout(() => {
    notification.remove();
  }, 3500);
};
var formatDate = (unixTimestamp) => new Date(unixTimestamp * 1e3).toLocaleString(window.navigator.language, {
  year: "numeric",
  month: "long",
  day: "numeric",
  weekday: "long",
  hour: "2-digit",
  minute: "2-digit"
});
var hideNode = (node) => {
  if (node) {
    node.classList.add("is-hidden");
  }
};
var showNode = (node) => {
  if (node) {
    node.classList.remove("is-hidden");
  }
};

// themes/default/public/js/list-invitations.js
var updateButtonsStatus = () => {
  const targetSelectionDOM = document.querySelectorAll(".target-selection");
  if (document.querySelectorAll(".selection .checkbox input:checked").length > 0) {
    targetSelectionDOM.forEach((node) => {
      node.disabled = false;
    });
  } else {
    targetSelectionDOM.forEach((node) => node.disabled = true);
  }
};
var updateSelection = (event) => {
  document.querySelectorAll(".item .checkbox input").forEach((node) => {
    node.checked = event.target.checked;
  });
  updateButtonsStatus();
};
var toggleHidden = () => {
  const invitationsListDOM = document.querySelector(".invitations-list");
  const toggleButtonDOM = document.querySelector(".action-toggle-hidden");
  const itemsHiddenDOM = invitationsListDOM.querySelectorAll(
    ".item[data-visibility='hidden']"
  );
  if (invitationsListDOM.dataset.visibility === "hidden") {
    toggleButtonDOM.innerText = i18n.hideText;
    itemsHiddenDOM.forEach((item) => showNode(item));
    invitationsListDOM.dataset.visibility = "shown";
  } else {
    toggleButtonDOM.innerText = i18n.showText;
    itemsHiddenDOM.forEach((item) => {
      hideNode(item);
      const checkbox = item.querySelector("input");
      if (checkbox.checked) {
        checkbox.click();
      }
    });
    invitationsListDOM.dataset.visibility = "hidden";
  }
};
var deleteInvitation = () => {
  if (confirm(i18n.confirmDeleteInvit)) {
    try {
      fetch(deleteURL, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"
        },
        body: getTokensBody()
      }).then((response) => {
        if (!response.ok) {
          throw new Error(`Request error: ${response.statusText}`);
        }
        return response.json();
      }).then((data) => {
        if (data.success) {
          data.tokens.forEach((t2) => {
            addToast(t2.msg, "success");
            document.getElementById(`row-${t2.token}`).remove();
          });
          data.failures.forEach((msg) => {
            addToast(msg, "error");
          });
          updateButtonsStatus();
        } else {
          data.failures.forEach((msg) => {
            addToast(msg, "error");
          });
          if (data.msg) {
            addToast(data.msg, "error");
          }
        }
      });
    } catch (error) {
      console.error(error);
    }
  }
};
var resendInvitation = () => {
  if (confirm(i18n.confirmResendMail)) {
    fetch(resendURL, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"
      },
      body: getTokensBody()
    }).then((response) => {
      if (!response.ok) {
        throw new Error(`Request error: ${response.statusText}`);
      }
      return response.json();
    }).then((data) => {
      if (data.success) {
        data.success.forEach((t2) => {
          const itemDOM = document.getElementById(`row-${t2.token}`);
          itemDOM.querySelector(".expiration-date").innerText = t2.expires;
          itemDOM.querySelector(".selection input").click();
          addToast(t2.msg, "success");
        });
        data.failures.forEach((msg) => {
          addToast(msg, "error");
        });
        updateButtonsStatus();
      }
    }).catch((error) => console.error(error));
  }
};
var toggleVisibility = () => {
  fetch(toggleURL, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"
    },
    body: getTokensBody()
  }).then((response) => {
    if (!response.ok) {
      throw new Error(`Request error: ${response.statusText}`);
    }
    return response.json();
  }).then((data) => {
    if (data.success) {
      data.tokens.forEach((t2) => {
        const itemDOM = document.getElementById(`row-${t2.token}`);
        if (t2.show) {
          itemDOM.setAttribute("data-visibility", "shown");
          showNode(itemDOM);
          itemDOM.querySelector(".selection .icon").classList.add("is-hidden");
        } else {
          itemDOM.setAttribute("data-visibility", "hidden");
          if (document.querySelector(".invitations-list").dataset.visibility === "hidden") {
            hideNode(itemDOM);
          }
          itemDOM.querySelector(".selection .icon").classList.remove("is-hidden");
        }
        itemDOM.querySelector(".selection input").click();
      });
      updateButtonsStatus();
    } else {
      addToast(data.msg, "error");
    }
  }).catch((error) => console.error(error));
};
var getTokensBody = () => {
  const tokens = new URLSearchParams();
  document.querySelectorAll(".selection input:checked").forEach((item) => tokens.append("tokens[]", item.dataset.token));
  return tokens;
};
var fillModal = (buttonDOM) => {
  const modalDOM = document.getElementById("modal-files-list");
  modalDOM.querySelector(".files-list").replaceChildren();
  modalDOM.querySelector("header .modal-card-title p").innerText = i18n.listFiles.replace("XX1", buttonDOM.dataset.token).replace("XX2", buttonDOM.dataset.guest);
  const files = buttonDOM.dataset.files ? JSON.parse(buttonDOM.dataset.files) : [];
  const itemList = new DocumentFragment();
  files.forEach((file) => {
    const expires = i18n.expiration.replace(
      "XXX",
      formatDate(file.delay * 86400 + file.created_at)
    );
    const item = document.querySelector("template#item").content.cloneNode(true).children[0];
    item.querySelector(".file-link").href = file.url;
    item.querySelector(".file-link").innerText = file.name;
    item.querySelector(".file-size").innerText = `(${E(
      file.size
    )}, ${expires})`;
    itemList.appendChild(item);
  });
  modalDOM.querySelector(".files-list").appendChild(itemList);
};
document.addEventListener("DOMContentLoaded", () => {
  document.querySelectorAll(".js-modal-trigger.action-files-info").forEach((node) => {
    node.addEventListener("click", () => {
      fillModal(node);
    });
  });
  document.querySelectorAll(".selection input").forEach((node) => node.onclick = updateButtonsStatus);
  document.getElementById("action-select-all").onclick = updateSelection;
  document.querySelector(".action-toggle-hidden").onclick = toggleHidden;
  document.querySelector(".action-delete-invitation").onclick = deleteInvitation;
  document.querySelector(".action-resend-invitation").onclick = resendInvitation;
  document.querySelector(".action-toggle-visibility").onclick = toggleVisibility;
});
